type Circle = { kind: "circle"; radius: number };
type Rectangle = { kind: "rectangle"; width: number; height: number };
// 1. Write a Triangle type here (kind "triangle", base, height) and add it to Shape.
type Triangle = { kind: "triangle"; base: number; height: number };

type Shape = Circle | Rectangle | Triangle;

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "rectangle":
      return shape.width * shape.height;
    // 2. Handle "triangle" here.
    case "triangle":
      return (shape.base * shape.height) / 2;
    default: {
      // Every kind handled above means nothing is left: shape is `never` here.
      // A kind without a case makes this line a type error.
      const unhandled: never = shape;
      return unhandled;
    }
  }
}

const shapes: Shape[] = [
  { kind: "circle", radius: 1 },
  { kind: "rectangle", width: 3, height: 2 },
  { kind: "triangle", base: 4, height: 5 },
];

// 3. querySelector returns null when nothing matches. Handle it (no ! allowed).
const list = document.querySelector("#areas");
if (!list) throw new Error("There's no #areas element on the page.");

for (const shape of shapes) {
  const item = document.createElement("li");
  item.textContent = `${shape.kind}: ${area(shape).toFixed(2)}`;
  list.append(item);
}

