    if (amount <= 0) return;
    this.total += amount;
    this.history.push(`+${amount}`);
  }

  // 1. withdraw(amount: number): boolean
  withdraw(amount: number): boolean {
    if (amount <= 0 || amount > this.total) return false;
    this.total -= amount;
    this.history.push(`-${amount}`);
    return true;
  }

  // 3. log(): string
  log(): string {
    return this.history.join(", ");
  }
}

